Derived Classes:  
- **book** → adds pages  
- **tape** → adds playing time  

We want:

```
media *m;
book b;
tape t;

m = &b;   → call book.display()
m = &t;   → call tape.display()
```

### ✔ Simple Clean Code

```cpp
#include <iostream>
using namespace std;

class media {
protected:
    string title;
    float price;

public:
    virtual void display() = 0; // pure virtual
};

class book : public media {
    int pages;

public:
    book(string t, float p, int pg) {
        title = t; price = p; pages = pg;
    }

    void display() {
        cout << "Book - " << title 
             << " | Price: " << price 
             << " | Pages: " << pages << endl;
    }
};

class tape : public media {
    float time;

public:
    tape(string t, float p, float tm) {
        title = t; price = p; time = tm;
    }

    void display() {
        cout << "Tape - " << title 
             << " | Price: " << price 
             << " | Time: " << time << endl;
    }
};

int main() {
    media *m;

    book b("C++", 300, 500);
    tape t("Java lecture", 150, 60);

    m = &b;
    m->display();      // book display

    m = &t;
    m->display();      // tape display
}
```

