# 🔥 8) Pure Virtual Function Example (Area of Shapes)

### Base class: Shape  
has pure virtual `area()`  
Derived: square, circle implement area()

### ✔ CODE:

```cpp
#include <iostream>
using namespace std;

class Shape {
protected:
    float l;

public:
    void set_data() {
        cin >> l;
    }

    virtual float area() = 0;  // pure virtual
};

class square : public Shape {
public:
    float area() {
        return (l * l);
    }
};

class circle : public Shape {
public:
    float area() {
        return 3.14 * l * l;
    }
};

int main() {
    square s;
    circle c;

    Shape *sh;

    cout << "enter length to calculate area of square:";
    sh = &s;
    sh->set_data();
    cout << "Area of square:" << sh->area() << endl;

    cout << "Enter radius to calculate area of circle:";
    sh = &c;
    sh->set_data();
    cout << "Area of circle:" << sh->area() << endl;

    return 0;
}
